#include "wav.hpp"
#include <AudioToolbox/AudioToolbox.h>
static Channels*current=nullptr;
static OSStatus supply(void*,AudioUnitRenderActionFlags*,const AudioTimeStamp*,UInt32,UInt32 frames,AudioBufferList*data){for(UInt32 c=0;c<data->mNumberBuffers;c++){if(!current||c>=current->size())return kAudio_ParamError;data->mBuffers[c].mData=(*current)[c].data();data->mBuffers[c].mDataByteSize=frames*sizeof(float);data->mBuffers[c].mNumberChannels=1;}return noErr;}
static OSType fourcc(const char*s){require(strlen(s)==4,"AU IDs must be four characters");return (uint32_t(s[0])<<24)|(uint32_t(s[1])<<16)|(uint32_t(s[2])<<8)|uint32_t(s[3]);}
int main(int argc,char**argv){try{require(argc>=5,"Usage: auralis-au subtype manufacturer input.wav output.wav");WaveReader reader(argv[3]);AudioComponentDescription desc{};desc.componentType=kAudioUnitType_Effect;desc.componentSubType=fourcc(argv[1]);desc.componentManufacturer=fourcc(argv[2]);AudioComponent component=AudioComponentFindNext(nullptr,&desc);require(component,"AUv2 effect not registered");AudioUnit unit=nullptr;require(AudioComponentInstanceNew(component,&unit)==noErr,"AU instantiation failed; asynchronous AUv3 is not supported");AudioStreamBasicDescription format{};format.mSampleRate=reader.rate;format.mFormatID=kAudioFormatLinearPCM;format.mFormatFlags=kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked|kAudioFormatFlagIsNonInterleaved;format.mBytesPerPacket=4;format.mFramesPerPacket=1;format.mBytesPerFrame=4;format.mChannelsPerFrame=reader.channels;format.mBitsPerChannel=32;for(auto scope:{kAudioUnitScope_Input,kAudioUnitScope_Output})require(AudioUnitSetProperty(unit,kAudioUnitProperty_StreamFormat,scope,0,&format,sizeof(format))==noErr,"AU format rejected");UInt32 maximum=512;require(AudioUnitSetProperty(unit,kAudioUnitProperty_MaximumFramesPerSlice,kAudioUnitScope_Global,0,&maximum,sizeof(maximum))==noErr,"AU block size rejected");AURenderCallbackStruct callback{supply,nullptr};require(AudioUnitSetProperty(unit,kAudioUnitProperty_SetRenderCallback,kAudioUnitScope_Input,0,&callback,sizeof(callback))==noErr,"AU callback rejected");require(AudioUnitInitialize(unit)==noErr,"AU initialize failed");Float64 latencySeconds=0;UInt32 size=sizeof(latencySeconds);AudioUnitGetProperty(unit,kAudioUnitProperty_Latency,kAudioUnitScope_Global,0,&latencySeconds,&size);uint32_t latency=std::llround(latencySeconds*reader.rate);std::vector<unsigned char>storage(sizeof(AudioBufferList)+(reader.channels-1)*sizeof(AudioBuffer));auto*list=(AudioBufferList*)storage.data();render(reader,argv[4],latency,[&](Channels&in,Channels&out,uint32_t n,uint64_t frame){current=&in;list->mNumberBuffers=reader.channels;for(UInt32 c=0;c<reader.channels;c++){list->mBuffers[c].mNumberChannels=1;list->mBuffers[c].mDataByteSize=n*sizeof(float);list->mBuffers[c].mData=out[c].data();}AudioTimeStamp time{};time.mFlags=kAudioTimeStampSampleTimeValid;time.mSampleTime=frame;AudioUnitRenderActionFlags flags=0;require(AudioUnitRender(unit,&flags,&time,0,n,list)==noErr,"AU render failed");});AudioUnitUninitialize(unit);AudioComponentInstanceDispose(unit);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
